function BrandIcon({domain,size=30}:{domain:string;size?:number}){
 return <img src={`https://www.google.com/s2/favicons?domain=${encodeURIComponent(domain)}&sz=64`} width={size} height={size} alt="" loading="lazy" className="shrink-0 rounded-lg object-contain"/>
}
function GuruBrandsCarousel(){
 const doubled=[...guruBrands,...guruBrands]
 return <div className="relative mt-6 overflow-hidden border-t border-white/10 pt-5 [mask-image:linear-gradient(to_right,transparent,black_8%,black_92%,transparent)]" aria-label="Ferramentas de IA disponíveis">
  <div className="cg2-guru-marquee flex w-max items-center gap-3 pr-3">
   {doubled.map(([name,domain],i)=><span key={`${name}-${i}`} className="inline-flex shrink-0 items-center gap-3 rounded-2xl border border-white/10 bg-black/30 px-4 py-3 text-sm font-bold"><BrandIcon domain={domain} size={36}/>{name}</span>)}
  </div>
 </div>
}
function SectionTitle({eyebrow,title,description}:{eyebrow:string;title:string;description:string}){
 return <div className="space-y-2"><span className="text-[10px] font-black uppercase tracking-[.27em] text-orange-400">{eyebrow}</span><h2 className="text-2xl font-black tracking-tight sm:text-[32px]">{title}</h2><p className="max-w-2xl text-[13px] leading-relaxed text-zinc-400 sm:text-sm">{description}</p></div>
}
function Hero({image,eyebrow,title,highlight,description,children}:{image:string;eyebrow:string;title:string;highlight:string;description:string;children?:React.ReactNode}){
 return <section className="relative isolate overflow-hidden rounded-[28px] border border-orange-500/20 bg-[#19131a] shadow-[0_32px_90px_rgba(0,0,0,.34)]">
  <img src={image} alt="" className="absolute inset-0 h-full w-full object-cover object-center" fetchPriority="high"/>
  <div className="pointer-events-none absolute inset-0 bg-gradient-to-r from-[#0e0b12]/95 via-[#160e11]/72 to-transparent"/>
  <div className="relative z-10 flex min-h-[322px] items-center px-6 py-9 sm:min-h-[390px] sm:px-10 xl:min-h-[425px] xl:px-14">
   <div className="max-w-[610px] pr-5"><span className="inline-flex items-center gap-2 rounded-full border border-orange-400/30 bg-black/35 px-3 py-2 text-[10px] font-extrabold tracking-[.2em] text-orange-300"><Sparkles size={14}/>{eyebrow}</span>
    <h1 className="mt-5 max-w-[600px] text-3xl font-black leading-[1.08] tracking-[-.05em] drop-shadow-md sm:text-5xl xl:text-[56px]">{title}<span className="block text-orange-400">{highlight}</span></h1>
    <p className="mt-4 max-w-[420px] text-sm leading-7 text-zinc-200 drop-shadow">{description}</p>
    <div className="mt-6 flex flex-wrap items-center gap-3">{children}</div>
   </div>
  </div>
  <div className="absolute bottom-0 h-1 w-full bg-gradient-to-r from-orange-500 via-orange-500/50 to-transparent"/>
 </section>
}
